import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = in.nextInt();
        int x = in.nextInt();

        int chap = 0, ong = n;
        while (chap < ong) {
            int orta = (chap + ong) / 2;
            if (a[orta] < x) chap = orta + 1;
            else ong = orta;
        }

        int[] b = new int[n + 1];
        for (int i = 0; i < chap; i++) b[i] = a[i];
        b[chap] = x;
        for (int i = chap; i < n; i++) b[i + 1] = a[i];

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i <= n; i++) {
            if (i > 0) sb.append(' ');
            sb.append(b[i]);
        }
        System.out.println(sb);
    }
}

